<?php
declare(strict_types=1); require __DIR__ . '/includes/bootstrap.php'; require_admin();
$playtestPath = __DIR__ . '/downloads/LivingRealms-Playtest-Windows-0.9.21.zip';
$playtestReady = is_file($playtestPath);
$playtestSize = $playtestReady ? number_format((float)filesize($playtestPath) / 1048576, 1) . ' MB' : 'Packaging';
$total = (int)db()->query('SELECT COUNT(*) FROM visitor_events')->fetchColumn();
$todayStmt = db()->prepare('SELECT COUNT(*) FROM visitor_events WHERE visited_at LIKE ?');
$todayStmt->execute([central_now()->format('Y-m-d') . '%']);
$today = (int)$todayStmt->fetchColumn();
$countries = (int)db()->query("SELECT COUNT(DISTINCT country_code) FROM visitor_events WHERE country_code IS NOT NULL")->fetchColumn();
$visits = db()->query('SELECT visited_at,ip_address,city,region,country_code,path,referrer_domain,user_agent,is_bot FROM visitor_events ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
$playerAccessEvents = db()->query('SELECT occurred_at,ip_address,email,action,successful FROM player_access_events ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
$pageTitle = 'Admin Portal | Living Realms'; require __DIR__ . '/includes/header.php'; ?>
<main class="portal-main"><p class="eyebrow">Administrator</p><h1>Visitor Activity</h1><div class="portal-tabs"><a href="/portal.php">Visitor Activity</a><a href="/portal-signups.php">Player Signups</a><a href="/portal-feedback.php">Bug &amp; Feature Reports</a><a href="#windows-playtest">Windows Playtest</a></div><div class="stats"><div class="panel stat"><strong><?= $total ?></strong>Total requests</div><div class="panel stat"><strong><?= $today ?></strong>Today (Central)</div><div class="panel stat"><strong><?= $countries ?></strong>Countries</div></div>
