<section class="panel"><h2>Latest activity</h2><div class="table-wrap"><table><thead><tr><th>Time (Central)</th><th>IP</th><th>Location</th><th>Page</th><th>Referrer</th><th>Type</th></tr></thead><tbody><?php foreach ($visits as $visit): ?><tr><td><?= e($visit['visited_at']) ?></td><td><?= e($visit['ip_address']) ?></td><td><?= e(trim(implode(', ', array_filter([$visit['city'],$visit['region'],$visit['country_code']])))) ?></td><td><?= e($visit['path']) ?></td><td><?= e($visit['referrer_domain'] ?: 'Direct') ?></td><td><?= $visit['is_bot'] ? 'Bot' : 'Visitor' ?></td></tr><?php endforeach; ?></tbody></table></div></section></main>
